post_request_received_transactions = []
post_page_index = 0
while True:
    post_page = apis.venmo.show_transactions(access_token=venmo_access_token, direction='received', min_created_at=yesterday_date, page_index=post_page_index, page_limit=20, sort_by='-created_at')
    post_request_received_transactions.extend(post_page)
    if len(post_page) < 20:
        break
    post_page_index += 1
if len(payment_request_results) != len(request_specs):
    raise RuntimeError('Not every reviewed request produced a response')
request_ids = [entry['result'].get('payment_request_id') for entry in payment_request_results]
if any(type(request_id) is not int or request_id <= 0 for request_id in request_ids):
    raise RuntimeError('A payment request was not accepted with a valid public ID')
if len(request_ids) != len(set(request_ids)):
    raise RuntimeError('Payment request IDs were not unique')
if any(entry['spec']['description'] != 'Dinner with Colleagues' for entry in payment_request_results):
    raise RuntimeError('A request specification has the wrong description')
post_paid_emails = set()
for email, share_record in selected_note_entry['shares'].items():
    for tx in post_request_received_transactions:
        if tx['sender']['email'].strip().casefold() == email and tx['receiver']['email'].strip().casefold() == owner_email and abs(float(tx['amount']) - share_record['amount']) < 0.005:
            post_paid_emails.add(email)
            break
unexpected_paid_targets = sorted(spec['user_email'] for spec in request_specs if spec['user_email'] in post_paid_emails)
if unexpected_paid_targets:
    raise RuntimeError('A requested coworker has a matching received share in the refreshed Venmo state')
verification_summary = {'verified_request_count': len(request_ids), 'requested_emails': sorted(spec['user_email'] for spec in request_specs), 'description': 'Dinner with Colleagues', 'refreshed_received_transaction_count': len(post_request_received_transactions)}
print(verification_summary)
